-- Migration: Year 2 - Hematology Pathology MCQs Part 3 (81-120)
-- Date: 2026-04-24

BEGIN;

DO $$
DECLARE
    v_topic_id UUID;
BEGIN
    INSERT INTO topics (title, slug, semester_id, year_id, "order")
    VALUES ('Hematology Pathology', 'hematology-pathology', 3, 2, 61)
    ON CONFLICT (slug) DO UPDATE SET year_id = 2, semester_id = 3
    RETURNING id INTO v_topic_id;

    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES

    -- AUTOIMMUNE HEMOLYTIC ANEMIA (81-88)
    (v_topic_id, 'Warm autoimmune hemolytic anemia (Warm AIHA) involves IgG antibodies reacting at body temperature. What is the mechanism of hemolysis?', '["IgG activates complement to lyse RBCs intravascularly", "IgG-coated RBCs are recognized by Fc receptors on splenic macrophages and destroyed extravascularly", "IgG causes agglutination in cold temperatures", "IgG activates neutrophils to destroy RBCs"]', 1, 'Warm AIHA: IgG binds RBC surface antigens at 37 degrees C. Splenic macrophages detect IgG via Fc receptors and phagocytose the RBCs (extravascular hemolysis). Spherocytes appear on smear (partial phagocytosis removes membrane). Direct Coombs (DAT) is POSITIVE for IgG.'),
    (v_topic_id, 'Which disease is most commonly associated with Warm AIHA?', '["Cold agglutinin disease from Mycoplasma", "Systemic lupus erythematosus (SLE) and Chronic Lymphocytic Leukemia (CLL)", "Infectious mononucleosis", "Paroxysmal cold hemoglobinuria"]', 1, 'Warm AIHA is most commonly idiopathic, or secondary to SLE (autoimmune) or CLL (neoplastic B-cells produce autoantibodies). It can also be drug-induced (methyldopa, penicillin).'),
    (v_topic_id, 'The Direct Coombs Test (Direct Antiglobulin Test, DAT) detects which of the following?', '["Anti-RBC antibodies in the patient serum", "IgG or complement (C3d) already bound to the patient''s own RBCs in vivo", "ABO compatibility", "Platelet antibodies"]', 1, 'The DAT detects antibodies or complement coating the patient''s own RBCs. Anti-human globulin (Coombs reagent) is added to washed patient RBCs. If IgG or C3 is present on the RBC surface, agglutination occurs. Positive DAT = immune-mediated hemolysis.'),
    (v_topic_id, 'Cold agglutinin disease (Cold AIHA) involves IgM antibodies active at temperatures below 37 degrees C. What is the mechanism of hemolysis?', '["IgM directly lyses RBCs via membrane insertion", "IgM agglutinates RBCs in cold peripheral blood, fixing complement (C3b). In warmer central circulation, IgM dissociates but C3b remains, directing splenic/hepatic macrophage destruction", "IgM stimulates NK cells to destroy RBCs", "IgM activates the coagulation cascade"]', 1, 'Cold AIHA: IgM binds RBCs in cold peripheral vessels, fixing C3b. As blood returns to the warm core, IgM dissociates. C3b-coated RBCs are destroyed by macrophages in liver (Kupffer cells) via complement receptors. DAT positive for C3, NOT IgG.'),
    (v_topic_id, 'The most common infection associated with Cold Agglutinin Disease is?', '["Epstein-Barr Virus (EBV) causing anti-i antibodies", "Mycoplasma pneumoniae causing anti-I antibodies", "CMV", "HIV"]', 1, 'Mycoplasma pneumoniae (walking pneumonia) classically causes cold agglutinin disease via anti-I antibodies (uppercase I = adult RBC antigen). EBV causes anti-i antibodies (lowercase i = fetal/cord blood antigen). Both cause transient cold AIHA.'),
    (v_topic_id, 'Paroxysmal Cold Hemoglobinuria (PCH) is caused by the Donath-Landsteiner antibody. What is unique about this IgG antibody?', '["It is a warm-reactive IgG attacking Rh antigens", "It binds RBCs in the cold (fixing complement) but causes lysis when the blood warms up to 37 degrees C (biphasic hemolysis)", "It is always associated with CLL", "It causes agglutination but not lysis"]', 1, 'The Donath-Landsteiner antibody is an IgG that binds to the P antigen on RBCs in cold temperatures, fixing complement. When blood returns to body temperature, complement activation proceeds to lysis. Classic association: syphilis (historically) or post-viral in children.'),
    (v_topic_id, 'Drug-induced immune hemolytic anemia can occur by three mechanisms. Penicillin causes hemolysis by which mechanism?', '["Penicillin generates ROS that oxidize hemoglobin (Heinz body hemolysis)", "Penicillin (hapten mechanism): drug binds to RBC membrane; IgG anti-drug antibodies attach to the drug-RBC complex, causing extravascular hemolysis", "Penicillin induces production of true autoantibodies against RBC antigens", "Penicillin activates complement directly on RBCs"]', 1, 'Hapten mechanism: drug (hapten) binds covalently to RBC proteins. Immune system makes IgG antibodies against the drug-protein complex. DAT: positive for IgG. Hemolysis stops when drug is discontinued. Classic drugs: high-dose penicillin, cephalosporins.'),
    (v_topic_id, 'Methyldopa causes drug-induced hemolytic anemia by which unique mechanism?', '["Hapten mechanism: methyldopa binds RBC membrane", "Immune complex mechanism: methyldopa-antibody complexes activate complement", "True autoantibody mechanism: methyldopa alters the immune system to produce genuine anti-Rh(e) autoantibodies against unmodified RBCs", "Oxidative hemolysis similar to G6PD deficiency"]', 2, 'Methyldopa (and other drugs like procainamide) induce true autoantibodies against native RBC antigens (usually Rh antigens). DAT is positive for IgG. This is the only drug mechanism where antibodies react with normal RBCs (not drug-coated RBCs). Hemolysis resolves weeks after stopping the drug.'),

    -- MICROANGIOPATHIC HEMOLYTIC ANEMIA: TTP, HUS, DIC (89-102)
    (v_topic_id, 'Thrombotic Thrombocytopenic Purpura (TTP) is caused by deficiency of which enzyme?', '["Factor VIII", "ADAMTS13 (a metalloprotease that cleaves ultra-large vWF multimers)", "Protein C", "Thrombomodulin"]', 1, 'ADAMTS13 normally cleaves ultra-large vWF multimers secreted by endothelial cells. In TTP, ADAMTS13 is deficient (autoimmune inhibitor or congenital), allowing massive vWF multimers to accumulate and platelet thrombi to form in microvasculature.'),
    (v_topic_id, 'The classic pentad of TTP includes which five findings?', '["Fever, thrombocytopenia, hemolytic anemia, renal failure, neurological changes", "Fever, splenomegaly, petechiae, DIC, jaundice", "Anemia, neutropenia, thrombocytopenia, renal failure, rash", "Thrombocytopenia, hepatomegaly, seizures, proteinuria, anemia"]', 0, 'TTP pentad: Fever + Thrombocytopenia + Microangiopathic Hemolytic Anemia (MAHA with schistocytes) + Renal failure (mild) + Neurological symptoms (confusion, seizures). In practice, the classic triad (MAHA + thrombocytopenia + neurological changes) is sufficient to start treatment.'),
    (v_topic_id, 'The treatment of choice for TTP is?', '["Platelet transfusion", "Plasma exchange (plasmapheresis) to remove ADAMTS13 inhibitor and replace functional ADAMTS13", "Heparin anticoagulation", "Splenectomy"]', 1, 'Plasma exchange removes the anti-ADAMTS13 autoantibodies and replaces deficient ADAMTS13 enzyme. It is life-saving and must be started urgently. Platelet transfusion is CONTRAINDICATED (fuels the thrombotic process).'),
    (v_topic_id, 'Why is platelet transfusion CONTRAINDICATED in TTP?', '["Platelets are already too high in TTP", "Transfused platelets are rapidly consumed by the endothelium-platelet interaction, causing more microvascular thrombosis (adding fuel to the fire)", "Platelets trigger ADAMTS13 production", "Platelets cause allergic reactions in TTP"]', 1, 'TTP is caused by uncontrolled platelet aggregation in microvessels. Giving more platelets provides more substrate for thrombosis, worsening ischemia to the brain and kidneys. The approach is to remove the trigger (plasma exchange) and suppress antibody production (steroids).'),
    (v_topic_id, 'Hemolytic Uremic Syndrome (HUS) classically presents in children after which infection?', '["Campylobacter jejuni gastroenteritis", "E. coli O157:H7 gastroenteritis (bloody diarrhea) producing Shiga toxin", "Salmonella typhi bacteremia", "Shigella sonnei gastroenteritis"]', 1, 'E. coli O157:H7 produces Shiga-like toxin (verotoxin), which damages renal glomerular endothelial cells, causing the HUS triad: MAHA + thrombocytopenia + acute renal failure. ADAMTS13 is normal in typical HUS. More common in children.'),
    (v_topic_id, 'The classic triad of HUS is?', '["Fever, neurological symptoms, thrombocytopenia", "Microangiopathic hemolytic anemia (MAHA), thrombocytopenia, and acute renal failure", "Bloody diarrhea, fever, and jaundice", "MAHA, thrombocytopenia, and neurological symptoms (same as TTP)"]', 1, 'HUS triad: MAHA + thrombocytopenia + acute renal failure (ARF). Unlike TTP, neurological symptoms are absent or mild and ARF is dominant. ADAMTS13 is normal. HUS occurs after Shiga toxin damages renal endothelium specifically.'),
    (v_topic_id, 'Disseminated Intravascular Coagulation (DIC) is characterized by simultaneous pathological clotting AND bleeding. What initiates DIC?', '["Platelet antibodies activating the immune system", "Massive release of tissue factor (TF) into the bloodstream, triggering uncontrolled systemic activation of both the coagulation cascade and fibrinolysis", "Deficiency of ADAMTS13", "Autoimmune complement activation on RBCs"]', 1, 'DIC is triggered by systemic tissue factor release: obstetric catastrophes (abruptio placentae, amniotic fluid embolism), gram-negative sepsis, trauma, malignancy (especially APML), and snake envenomation. Widespread clotting consumes all coagulation factors and platelets, then fibrinolysis produces FDPs (D-dimers).'),
    (v_topic_id, 'Which lab pattern is most consistent with Disseminated Intravascular Coagulation (DIC)?', '["Elevated PT, elevated aPTT, low platelets, elevated D-dimers, low fibrinogen, schistocytes on smear", "Normal PT, elevated aPTT, low platelets, normal D-dimers", "Low PT, low aPTT, elevated platelets, low D-dimers", "Elevated PT only with normal aPTT and normal platelets"]', 0, 'DIC lab pattern: ALL coagulation times prolonged (PT + aPTT both elevated) + thrombocytopenia (platelet consumption) + elevated D-dimers and FDPs (fibrinolysis) + LOW fibrinogen (consumed) + schistocytes (MAHA from fibrin strands). Hypofibrinogenemia distinguishes DIC from liver disease.'),
    (v_topic_id, 'Which malignancy has the HIGHEST association with DIC?', '["Chronic lymphocytic leukemia", "Acute Promyelocytic Leukemia (APL/APML, AML-M3) — promyelocytes release massive amounts of tissue factor", "Multiple myeloma", "Follicular lymphoma"]', 1, 'APL (M3) promyelocytes contain granules packed with thromboplastic (tissue factor) material. When these granules release upon cell lysis (including during chemotherapy), they trigger devastating DIC. All-trans retinoic acid (ATRA) is used to differentiate promyelocytes and is given BEFORE chemotherapy to prevent DIC.'),
    (v_topic_id, 'In DIC, which finding differentiates it from liver disease (which also prolongs PT, reduces platelets, and lowers clotting factors)?', '["Elevated AST/ALT", "Elevated D-dimers (fibrin split products) and schistocytes on smear (MAHA), which are absent in pure liver disease", "Elevated bilirubin", "Low albumin"]', 1, 'Both DIC and liver disease lower clotting factors and prolong PT. However, DIC specifically shows elevated D-dimers (fibrinolysis from intravascular clotting) and schistocytes (MAHA from fibrin strands shearing RBCs). These findings are absent in pure hepatocellular disease.'),
    (v_topic_id, 'Treatment of DIC focuses primarily on?', '["Giving platelets only", "Treating the underlying triggering cause (e.g., deliver the baby, treat sepsis, start ATRA for APL) plus supportive replacement of consumed blood products", "Heparin for all patients with DIC", "Antifibrinolytics (aminocaproic acid) for all patients"]', 1, 'The ONLY definitive treatment is eliminating the trigger. Supportive: FFP (replaces consumed factors), cryoprecipitate (replaces fibrinogen and factor VIII), and platelet transfusions. Heparin is considered in thrombosis-predominant DIC (chronic DIC from malignancy).'),
    (v_topic_id, 'Paroxysmal Nocturnal Hemoglobinuria (PNH) is caused by a somatic mutation in which gene?', '["BRCA1", "PIG-A gene, causing absence of GPI-anchored proteins (including CD55 and CD59) on blood cell surfaces", "JAK2 V617F", "ADAMTS13"]', 1, 'PIG-A mutation prevents GPI-anchor synthesis. GPI-anchored proteins CD55 (DAF) and CD59 normally protect RBCs from complement lysis. Without them, complement destroys RBCs intravascularly, causing hemoglobin in the urine (hemoglobinuria), especially at night.'),
    (v_topic_id, 'Why does hemoglobinuria in PNH classically occur at night (noticed as dark red/brown morning urine)?', '["The kidneys produce less urine at night, concentrating hemoglobin", "Nocturnal hypoventilation causes mild respiratory acidosis, which activates complement more efficiently", "RBCs are larger at night", "Aldosterone is higher at night"]', 1, 'During sleep, mild CO2 retention → slight respiratory acidosis → complement activation increases. Complement lyses GPI-anchor-deficient RBCs intravascularly, releasing free hemoglobin. Hemoglobin is filtered by kidneys, turning urine dark. Morning urine contains the accumulated overnight hemoglobin.'),
    (v_topic_id, 'PNH patients are at high risk for which potentially fatal complication?', '["Chronic kidney disease from iron loss", "Venous thrombosis (especially of hepatic veins causing Budd-Chiari syndrome and cerebral veins)", "Bacterial pneumonia", "Acute leukemic transformation"]', 1, 'The mechanism of thrombosis in PNH: free hemoglobin released from lysed RBCs scavenges nitric oxide (NO), causing vasoconstriction and platelet activation. Also, complement-activated platelets increase procoagulant activity. Budd-Chiari syndrome from hepatic vein thrombosis is classic.'),

    -- APLASTIC ANEMIA (103-108)
    (v_topic_id, 'Aplastic anemia is characterized by pancytopenia with a hypocellular bone marrow. What is the most common pathophysiology?', '["Replacement of marrow by fibrosis", "Autoimmune T-cell destruction of hematopoietic stem cells, leaving marrow with fat cells replacing normal hematopoietic cells", "Nutritional deficiency of multiple vitamins", "Malignant infiltration of the marrow"]', 1, 'In most cases of acquired aplastic anemia, autoreactive CD8+ cytotoxic T-cells destroy hematopoietic stem cells. This is why immunosuppression (anti-thymocyte globulin + cyclosporine) works. Bone marrow biopsy shows hypocellular marrow with fat replacement.'),
    (v_topic_id, 'Which of the following is a well-recognized cause of aplastic anemia?', '["Autoimmune hemolysis", "Chloramphenicol, benzene exposure, radiation, parvovirus B19 (transient), and hepatitis viruses", "Iron deficiency", "Folate deficiency"]', 1, 'Aplastic anemia causes: drugs (chloramphenicol, NSAIDs, gold), toxins (benzene, radiation), viral infections (hepatitis viruses, EBV, CMV, parvovirus B19 in immunocompromised), and Fanconi anemia (congenital). Chloramphenicol is the classic drug-induced cause.'),
    (v_topic_id, 'Fanconi anemia is a congenital aplastic anemia. What is the mechanism?', '["Autoimmune T-cell destruction of stem cells", "Defective DNA repair pathway for interstrand crosslinks, causing accumulation of DNA damage in hematopoietic stem cells", "Absent erythropoietin production", "Splenic sequestration of normal marrow cells"]', 1, 'Fanconi anemia involves mutations in FANC genes encoding proteins for the Fanconi DNA repair pathway (repairs interstrand crosslinks). Result: progressive pancytopenia + physical anomalies (absent radii/thumbs, cafe-au-lait spots, short stature, genitourinary malformations). High risk of AML and squamous cell carcinomas.'),
    (v_topic_id, 'A 25-year-old with aplastic anemia has a matched sibling donor. What is the first-line treatment?', '["Immunosuppression with anti-thymocyte globulin (ATG) + cyclosporine", "Allogeneic hematopoietic stem cell transplantation (HSCT)", "G-CSF + EPO", "Corticosteroids alone"]', 1, 'For young patients (<40 years) with a matched sibling donor, allogeneic HSCT is curative and preferred. For older patients or those without a matched donor, immunosuppression (ATG + cyclosporine + eltrombopag) is used.'),
    (v_topic_id, 'Diamond-Blackfan anemia is a pure red cell aplasia. How does it differ from aplastic anemia?', '["Diamond-Blackfan involves all cell lines and is acquired in adults", "Diamond-Blackfan selectively affects only the erythroid lineage (pure red cell aplasia), is congenital, and is caused by ribosomal protein gene mutations", "Diamond-Blackfan is caused by B12 deficiency", "Diamond-Blackfan responds to ATG"]', 1, 'Diamond-Blackfan: congenital pure red cell aplasia (erythroid precursors absent, other cell lines intact) with macrocytic anemia, elevated HbF, elevated EPO, physical anomalies (triphalangeal thumbs), and ribosomal protein mutations (RPS19 most common). Responds to corticosteroids.'),
    (v_topic_id, 'Transient aplastic crisis in patients with chronic hemolytic anemias (sickle cell, HS) is most commonly caused by?', '["EBV infecting B-lymphocytes", "Parvovirus B19 directly infecting and destroying erythroid progenitor cells (pronormoblasts) in bone marrow", "Folate deficiency from increased demands", "Drug toxicity from hydroxyurea"]', 1, 'Parvovirus B19 uses erythrocyte P antigen as a receptor and specifically infects pronormoblasts, halting red cell production. In normal individuals, this causes a mild self-limited anemia. In chronic hemolytic anemia patients who compensate with 3-5x normal erythropoiesis, marrow shutdown causes life-threatening aplastic crisis.'),

    -- POLYCYTHEMIA (109-115)
    (v_topic_id, 'Polycythemia Vera (PV) is a myeloproliferative neoplasm. What mutation is found in >95% of cases?', '["BCR-ABL translocation", "JAK2 V617F point mutation, causing constitutive JAK2 kinase activation and growth factor-independent erythropoiesis", "NPM1 mutation", "FLT3-ITD mutation"]', 1, 'JAK2 V617F is the hallmark of PV (also found in 50% of essential thrombocythemia and primary myelofibrosis). The valine-to-phenylalanine substitution activates JAK2 constitutively, mimicking persistent EPO receptor signaling and driving autonomous RBC production.'),
    (v_topic_id, 'What is the classic symptom of Polycythemia Vera that helps distinguish it from secondary polycythemia?', '["Dyspnea on exertion", "Aquagenic pruritus (itching after a warm bath/shower) from histamine release by increased basophils and mast cells", "Night sweats", "Bone pain"]', 1, 'Aquagenic pruritus is pathognomonic of PV (or systemic mastocytosis). Water (especially warm) triggers basophil degranulation and histamine release. Secondary polycythemia (from EPO excess) does NOT cause pruritus.'),
    (v_topic_id, 'Laboratory findings in Polycythemia Vera include which of the following?', '["Elevated RBC mass, low EPO, elevated WBC, elevated platelets, low oxygen saturation", "Elevated RBC mass, low EPO, often elevated WBC and platelets, normal or elevated O2 saturation", "Elevated RBC mass, high EPO, normal WBC, normal platelets", "Elevated RBC mass, high EPO, low WBC and platelets"]', 1, 'PV: elevated RBC + LOW EPO (autonomous production, feedback suppressed) + often elevated WBC and platelets (panmyelosis) + normal SaO2. Secondary polycythemia has HIGH EPO. Low EPO is the key to distinguishing PV from secondary causes.'),
    (v_topic_id, 'Why do patients with Polycythemia Vera have an increased risk of both thrombosis AND bleeding?', '["Platelet count is always low in PV", "Elevated RBC mass increases blood viscosity (promoting thrombosis); elevated platelets + acquired vWD from platelet consumption cause bleeding", "Aspirin therapy causes bleeding; hyperviscosity causes thrombosis", "DIC occurs in all PV patients"]', 1, 'High hematocrit → hyperviscosity → sluggish blood flow → stroke, Budd-Chiari syndrome, DVT. High platelet count → thrombosis risk. But extreme thrombocytosis causes acquired vWD (large vWF multimers are consumed by platelets), paradoxically increasing bleeding risk.'),
    (v_topic_id, 'The treatment of choice for Polycythemia Vera to reduce thrombosis risk acutely is?', '["Erythropoietin administration", "Therapeutic phlebotomy (to reduce hematocrit to <45%) and low-dose aspirin", "Hydroxyurea as first-line for all patients", "Splenectomy"]', 1, 'Phlebotomy reduces blood viscosity and is the cornerstone of PV management. Target Hct <45% in men, <42% in women. Low-dose aspirin prevents thrombosis without significantly increasing bleeding risk. Hydroxyurea is added for high-risk patients (age >60 or prior thrombosis).'),
    (v_topic_id, 'Which long-term complication can Polycythemia Vera transform into?', '["Chronic lymphocytic leukemia", "Myelofibrosis (spent phase) or acute leukemia (AML)", "Multiple myeloma", "Essential thrombocythemia"]', 1, 'PV can transform into: (1) Post-PV myelofibrosis (marrow replaced by fibrosis, massive splenomegaly from extramedullary hematopoiesis, teardrop cells on smear) or (2) AML (blast transformation, especially in patients treated with alkylating agents or P-32).'),
    (v_topic_id, 'Secondary polycythemia is characterized by an elevated EPO level. Which condition is the most common cause of secondary polycythemia?', '["Polycythemia Vera (JAK2 mutation)", "Chronic hypoxia (e.g., COPD, high altitude, sleep apnea) stimulating EPO production by renal peritubular cells", "Renal cell carcinoma producing ectopic EPO", "Cushing syndrome"]', 1, 'Most secondary polycythemia is physiologically appropriate: chronic hypoxia stimulates renal EPO production to increase oxygen-carrying capacity. Key labs: elevated Hct + elevated EPO + low SaO2 (if hypoxia-driven). Inappropriate secondary polycythemia: renal cell carcinoma, hepatocellular carcinoma, cerebellar hemangioblastoma secreting ectopic EPO.'),

    -- WHITE BLOOD CELL DISORDERS (116-120)
    (v_topic_id, 'A left shift on a CBC differential report means?', '["Decreased neutrophil count", "Increased immature neutrophil forms (bands, metamyelocytes, myelocytes) in peripheral blood, indicating marrow stress from severe infection or inflammation", "Lymphocyte predominance", "Decreased granulocyte production"]', 1, 'A left shift indicates marrow is releasing immature neutrophil precursors (bands = stab cells, then metamyelocytes, myelocytes) due to overwhelming demand. Causes: bacterial sepsis, severe inflammation. Distinguished from CML by absence of basophilia, eosinophilia, and Philadelphia chromosome.'),
    (v_topic_id, 'A leukemoid reaction mimics leukemia with extremely elevated WBC (>50,000). What distinguishes it from Chronic Myelogenous Leukemia (CML)?', '["WBC count — leukemoid reactions never exceed 30,000", "Leukoid reaction shows HIGH leukocyte alkaline phosphatase (LAP) score and is BCR-ABL NEGATIVE; CML shows LOW LAP and is BCR-ABL POSITIVE", "Leukemoid reactions always have blast cells", "CML has eosinophilia but leukemoid reactions do not"]', 1, 'LAP (leukocyte alkaline phosphatase) is high in reactive neutrophils (leukemoid reaction, PV) and LOW in CML neutrophils (neoplastic cells are metabolically less active). BCR-ABL translocation (Philadelphia chromosome, t(9;22)) is the definitive test for CML.'),
    (v_topic_id, 'Neutropenia is defined as an absolute neutrophil count (ANC) below 1500/mcL. Which ANC level is associated with the HIGHEST risk of life-threatening opportunistic infections?', '["ANC <1500 (mild neutropenia)", "ANC <1000 (moderate neutropenia)", "ANC <500 (severe neutropenia) — risk of bacterial and fungal sepsis dramatically increases", "ANC <200 (profound neutropenia)"]', 2, 'Risk stratification: ANC 500-1000 = moderate risk; ANC <500 = severe neutropenia with very high infection risk; ANC <100 = profound neutropenia requiring isolation and prophylactic antibiotics. Common causes: chemotherapy, aplastic anemia, drug toxicity (clozapine), autoimmune.'),
    (v_topic_id, 'Reactive lymphocytosis with atypical lymphocytes (large, with abundant pale cytoplasm and irregular nuclei) on peripheral smear is most characteristically seen in?', '["Acute lymphoblastic leukemia", "Infectious mononucleosis from EBV (atypical lymphocytes are reactive CD8+ T-cells responding to EBV-infected B-cells)", "CLL", "Toxoplasmosis"]', 1, 'Atypical lymphocytes (Downey cells) in EBV mononucleosis are REACTIVE CD8+ T-cells (not the infected B-cells). They have abundant basophilic cytoplasm that wraps around adjacent RBCs (clumped chromatin). Heterophile antibody (Monospot test) is positive in EBV mononucleosis.'),
    (v_topic_id, 'Eosinophilia (absolute eosinophil count >500/mcL) is most commonly caused by?', '["Bacterial infections", "Parasitic infections (especially tissue-invasive helminths) and allergic/atopic conditions", "Viral infections", "Fungal infections"]', 1, 'The two big causes of eosinophilia: (1) Helminth infections (tissue invasive: Toxocara, Strongyloides, Trichinella, Ascaris during migration). Note: intestinal helminths without tissue invasion may not cause eosinophilia. (2) Atopic diseases (asthma, allergic rhinitis, eczema, drug reactions). Mnemonic: NAACP (Neoplasm, Allergy, Addison, Collagen vascular disease, Parasites).')

    ON CONFLICT DO NOTHING;

END $$;

COMMIT;
